/* Regenerates assets/js/generated/screens-bundle.js from screens/*.html.
   Only needed for opening index.html directly from disk (file://), where browsers block fetch().
   Usage (from the project root):  node tools/bundle-screens.js */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const dir = path.join(root, 'screens');
const files = fs.readdirSync(dir).filter(f => /^screen-\d+-.*\.html$/.test(f)).sort();

const bundle = {};
files.forEach(f => { bundle['screens/' + f] = fs.readFileSync(path.join(dir, f), 'utf8'); });

const out = '/* AUTO-GENERATED by tools/bundle-screens.js — do not edit. Edit screens/*.html instead. */\n' +
  'window.NUTRILABEL_SCREEN_BUNDLE = ' + JSON.stringify(bundle, null, 2) + ';\n';
fs.writeFileSync(path.join(root, 'assets/js/generated/screens-bundle.js'), out);
console.log('Bundled ' + files.length + ' screens.');
